   fn practice_find_number() {
       use crate::syntax::LinkedNode; // 视实际导入调整，或直接 crate::LinkedNode
       let id = crate::Source::detached("= Head <label>").id();
       let mut root = crate::parse("= Head <label>");
       root.numberize(id, 0..64u64).unwrap();

       // 取 Text 节点的 span（它的编号应为 11，见 4.2.4）
       let text_span = root
           .descendants()
           .find(|n| n.kind() == crate::SyntaxKind::Text)
           .unwrap()
           .span();

