       let id = crate::Source::detached("= Head <label>").id();
       let mut root = crate::parse("= Head <label>");
       // 这棵树有 8 个节点，至少需要宽度 8；0..4 装不下
       let res = root.numberize(id, 0..4u64);
       assert!(res.is_err(), "窄区间应返回 Unnumberable");
       println!("numberize 返回: {:?}", res);
   }
   ```

2. 运行（**待本地验证**）：

   ```bash
